@keyframes glow-sweep-577b5b7b { 
  0% { left: -50%; transform: translate(-50%, -50%); }
  100% { left: 150%; transform: translate(-50%, -50%); }
}

@keyframes swipe-out-left { 
  0% { transform: var(--y) translateX(var(--swipe-amount-x)); opacity: 1; }
  100% { transform: var(--y) translateX(calc(var(--swipe-amount-x) - 100%)); opacity: 0; }
}

@keyframes swipe-out-right { 
  0% { transform: var(--y) translateX(var(--swipe-amount-x)); opacity: 1; }
  100% { transform: var(--y) translateX(calc(var(--swipe-amount-x) + 100%)); opacity: 0; }
}

@keyframes swipe-out-up { 
  0% { transform: var(--y) translateY(var(--swipe-amount-y)); opacity: 1; }
  100% { transform: var(--y) translateY(calc(var(--swipe-amount-y) - 100%)); opacity: 0; }
}

@keyframes swipe-out-down { 
  0% { transform: var(--y) translateY(var(--swipe-amount-y)); opacity: 1; }
  100% { transform: var(--y) translateY(calc(var(--swipe-amount-y) + 100%)); opacity: 0; }
}

@media (width <= 600px) {
  [data-sonner-toaster] { right: var(--mobile-offset-right); left: var(--mobile-offset-left); width: 100%; position: fixed; }
  [data-sonner-toaster][dir="rtl"] { left: calc(var(--mobile-offset-left)*-1); }
  [data-sonner-toaster] [data-sonner-toast] { width: calc(100% - var(--mobile-offset-left)*2); left: 0px; right: 0px; }
  [data-sonner-toaster][data-x-position="left"] { left: var(--mobile-offset-left); }
  [data-sonner-toaster][data-y-position="bottom"] { bottom: calc(var(--mobile-offset-bottom) + max(env(safe-area-inset-bottom), 0px)); }
  [data-sonner-toaster][data-y-position="top"] { top: calc(var(--mobile-offset-top) + max(env(safe-area-inset-top), 0px)); }
  [data-sonner-toaster][data-x-position="center"] { left: var(--mobile-offset-left); right: var(--mobile-offset-right); transform: none; }
}

@keyframes sonner-fade-in { 
  0% { opacity: 0; transform: scale(0.8); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes sonner-fade-out { 
  0% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.8); }
}

@media (prefers-reduced-motion) {
  .sonner-loading-bar, [data-sonner-toast], [data-sonner-toast] > * { transition: none !important; animation: auto ease 0s 1 normal none running none !important; }
}

@keyframes orbit-15552dba { 
  0% { transform: translateX(var(--gap)) scale(1); z-index: 1; }
  25% { z-index: 0; transform: translate(0px) scale(0.75); }
  50% { transform: translateX(calc(var(--gap)*-1)) scale(1); z-index: 1; }
  75% { z-index: 2; transform: translate(0px) scale(1.25); }
  100% { transform: translateX(var(--gap)) scale(1); z-index: 1; }
}

